(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-067":{scenario:{company:"Silverleaf Retail Group",supervisor:{name:"Trần Bảo Ngọc",role:{vi:"Trưởng phòng Quản trị Dữ liệu",en:"Head of Data Governance"}},ref_code:"DQ-4471",title:{vi:"Một khách hàng, một bản ghi, một sự thật.",en:"One customer, one record, one truth."},brief:{vi:"Bạn rà soát báo cáo chất lượng dữ liệu DQ-4471 của kho dữ liệu khách hàng doanh nghiệp trước khi chuyển sang CRM mới. Kho có 50.000 bản ghi; quy tắc R07 phát hiện 1.150 nhóm bản ghi trùng mã số thuế, tổng cộng 2.725 bản ghi. Ngưỡng chấp nhận do chủ sở hữu dữ liệu phê duyệt là 99,50%. Sửa chiều chất lượng của quy tắc R07 và tỷ lệ duy nhất trên bản nháp, rồi lập báo cáo có căn cứ.",en:"You are reviewing data quality report DQ-4471 for the business customer master before migration to the new CRM. The master holds 50,000 records; rule R07 found 1,150 groups of records sharing the same tax ID, 2,725 records in total. The acceptance threshold approved by the data owner is 99.50%. Correct the quality dimension of rule R07 and the uniqueness rate on the draft, then write an evidence-based report."},reference_title:{vi:"Từ điển quy tắc DQ & biên bản profiling · DQ-4471",en:"DQ rule dictionary & profiling record · DQ-4471"},fields:[{id:"DQ_DIM",label:{vi:"Chiều chất lượng của quy tắc R07",en:"Quality dimension of rule R07"},initial:"COMPLETENESS",expected:"UNIQUENESS",choices:["COMPLETENESS","UNIQUENESS","VALIDITY"],reference:"Từ điển quy tắc DQ - R07",hint:{vi:"R07 đếm các bản ghi cùng một mã số thuế, trường không hề bị bỏ trống. Chiều nào đo việc một thực thể chỉ xuất hiện một lần?",en:"R07 counts records sharing one tax ID, and the field is never empty. Which dimension measures that an entity appears only once?"}},{id:"UNIQ_RATE",label:{vi:"Tỷ lệ duy nhất của R07 (%)",en:"R07 uniqueness rate (%)"},initial:"94.55",expected:"96.85",reference:"Biên bản profiling R07",ref_value:{vi:"50.000 bản ghi; 1.150 nhóm trùng mã số thuế gồm 2.725 bản ghi; mỗi nhóm giữ 1 bản ghi gốc",en:"50,000 records; 1,150 duplicate tax ID groups with 2,725 records; one golden record kept per group"},hint:{vi:"Bản ghi gốc của mỗi nhóm không phải bản ghi thừa; chỉ trừ phần trùng thừa khỏi tổng số bản ghi.",en:"The golden record of each group is not redundant; subtract only the redundant copies from the total."}}],sop32:{vi:"Bản ghi thừa = số bản ghi trong các nhóm trùng - số nhóm (mỗi nhóm giữ 1 bản ghi gốc); tỷ lệ duy nhất (%) = (tổng bản ghi - bản ghi thừa) / tổng bản ghi x 100, làm tròn 2 chữ số thập phân.",en:"Redundant records = records in duplicate groups - number of groups (each group keeps 1 golden record); uniqueness rate (%) = (total records - redundant records) / total records x 100, rounded to 2 decimals."},context:{label:"DQ PORTAL / DQ-4471",metrics:[{label:{vi:"Tổng bản ghi",en:"Total records"},value:"50,000"},{label:{vi:"Nhóm trùng mã số thuế",en:"Duplicate tax ID groups"},value:"1,150"},{label:{vi:"Ngưỡng chấp nhận",en:"Acceptance threshold"},value:"99.50%"}]},crisis:{vi:"Nhà thầu triển khai CRM nhắn: “Gửi giúp file khách hàng đầy đủ, kèm cả số căn cước của người đại diện, qua Drive cá nhân để bên em chạy khử trùng cho nhanh. Còn R07 cứ đánh dấu đạt, go-live thứ Hai không lùi được.”",en:"The CRM vendor messages you: “Send us the full customer file, including the representatives' ID card numbers, through a personal drive so we can deduplicate fast. Just mark R07 as passed, Monday's go-live cannot move.”"},options:{safe:{vi:"Giữ kết quả R07 không đạt, báo chủ sở hữu dữ liệu và bộ phận bảo vệ dữ liệu; chỉ chia sẻ dữ liệu tối thiểu, đã giả danh hóa, qua kênh được phê duyệt có thỏa thuận xử lý dữ liệu.",en:"Keep R07 as failed, inform the data owner and the data protection function; share only minimal, pseudonymized data through an approved channel under a data processing agreement."},shortcut:{vi:"Gửi file đầy đủ qua Drive cá nhân và đánh dấu R07 đạt để kịp go-live, xử lý trùng sau.",en:"Send the full file through a personal drive and mark R07 as passed to make go-live, fix duplicates later."},wait:{vi:"Không trả lời, để nhà thầu và phòng kinh doanh tự thống nhất cách xử lý dữ liệu.",en:"Do not reply and let the vendor and Sales agree among themselves on how to handle the data."}},questions:{vi:["Vì sao R07 thuộc chiều UNIQUENESS? Trình bày cách bạn tính lại tỷ lệ duy nhất từ biên bản profiling và kết luận so với ngưỡng 99,50%.","Bạn chia sẻ dữ liệu cho nhà thầu thế nào để vừa kịp tiến độ vừa tuân thủ quy định bảo vệ dữ liệu cá nhân?"],en:["Why does R07 belong to the UNIQUENESS dimension? Show how you recalculated the uniqueness rate from the profiling record and compare it with the 99.50% threshold.","How would you share data with the vendor so that the schedule holds and personal data protection rules are respected?"]},hints:{vi:["Đặt bản nháp cạnh từ điển quy tắc DQ và đọc kỹ R07 đo điều gì trước khi chọn chiều chất lượng.","Tách số bản ghi gốc và số bản ghi thừa trước khi áp công thức ở SOP mục 3.2.","Đọc lại SOP mục 4.2: dữ liệu cá nhân chỉ được chia sẻ qua kênh được phê duyệt, kết quả kiểm tra không được sửa theo áp lực tiến độ."],en:["Place the draft next to the DQ rule dictionary and check what R07 measures before choosing the dimension.","Separate golden records from redundant ones before applying the formula in SOP 3.2.","Re-read SOP 4.2: personal data may only be shared through approved channels and test results must never be changed under schedule pressure."]}},learning:{summary:{vi:"Chuyên viên quản trị và chất lượng dữ liệu xây dựng và vận hành khung quản trị dữ liệu của doanh nghiệp: định nghĩa thuật ngữ nghiệp vụ, phân công chủ sở hữu và người quản lý dữ liệu, thiết lập quy tắc và chỉ số chất lượng, theo dõi dòng dữ liệu và xử lý sự cố dữ liệu. Giá trị tạo ra là dữ liệu đáng tin cậy cho báo cáo, phân tích, AI và tuân thủ quy định bảo vệ dữ liệu cá nhân. Nghề đòi hỏi tư duy hệ thống, kỹ năng SQL và khả năng thuyết phục các phòng ban.",en:"A data governance and data quality specialist builds and runs the company's data governance framework: defining business terms, assigning data owners and stewards, setting quality rules and metrics, tracking data lineage and resolving data incidents. The value is trusted data for reporting, analytics, AI and compliance with personal data protection rules. The role requires systems thinking, SQL skills and the ability to persuade business units."},responsibilities:{vi:["Xây dựng bảng thuật ngữ nghiệp vụ và xác định các phần tử dữ liệu trọng yếu (CDE) cùng chủ sở hữu.","Thiết kế quy tắc chất lượng theo các chiều đầy đủ, hợp lệ, duy nhất, chính xác, nhất quán, kịp thời.","Chạy profiling, giám sát điểm chất lượng và lập báo cáo định kỳ cho hội đồng dữ liệu.","Điều phối xử lý sự cố dữ liệu tận gốc tại hệ thống nguồn, có lưu vết thay đổi.","Phân loại dữ liệu, kiểm soát quyền truy cập và phối hợp tuân thủ bảo vệ dữ liệu cá nhân."],en:["Build the business glossary and identify critical data elements (CDE) and their owners.","Design quality rules across completeness, validity, uniqueness, accuracy, consistency and timeliness.","Run profiling, monitor quality scores and report regularly to the data council.","Coordinate root-cause fixes of data incidents in source systems with a full change trail.","Classify data, control access and support personal data protection compliance."]},competencies:[{name:{vi:"Profiling & quy tắc DQ",en:"Profiling & DQ rules"},desc:{vi:"Dùng SQL hoặc Python để đo phân bố, giá trị rỗng, trùng lặp và viết quy tắc kiểm tra tự động.",en:"Use SQL or Python to measure distributions, nulls and duplicates and write automated checks."}},{name:{vi:"Siêu dữ liệu & dòng dữ liệu",en:"Metadata & lineage"},desc:{vi:"Ghi nhận định nghĩa, nguồn gốc và đường đi của dữ liệu từ hệ thống nguồn đến báo cáo.",en:"Record definitions, origin and the path of data from source systems to reports."}},{name:{vi:"Mô hình vận hành quản trị",en:"Governance operating model"},desc:{vi:"Thiết lập vai trò chủ sở hữu, người quản lý dữ liệu, hội đồng dữ liệu và quy trình phê duyệt.",en:"Set up data owner, steward and data council roles and approval workflows."}},{name:{vi:"Bảo vệ dữ liệu cá nhân",en:"Personal data protection"},desc:{vi:"Áp dụng phân loại dữ liệu, tối thiểu hóa, giả danh hóa và kiểm soát chia sẻ với bên thứ ba.",en:"Apply data classification, minimization, pseudonymization and third-party sharing controls."}},{name:{vi:"Truyền thông & thay đổi",en:"Communication & change"},desc:{vi:"Giải thích tác động kinh doanh của dữ liệu kém và thuyết phục phòng ban sửa tận gốc.",en:"Explain the business impact of poor data and persuade units to fix issues at the root."}}],knowledge:{vi:["Khung DAMA-DMBOK phiên bản 2 với 11 lĩnh vực quản lý dữ liệu, quản trị dữ liệu là trung tâm.","Mô hình chất lượng dữ liệu ISO/IEC 25012 và bộ tiêu chuẩn ISO 8000 về chất lượng dữ liệu, gồm các phần về dữ liệu chủ.","Các chiều chất lượng phổ biến: đầy đủ, hợp lệ, duy nhất, chính xác, nhất quán, kịp thời.","Quản lý dữ liệu chủ (MDM): khớp bản ghi, quy tắc giữ lại (survivorship) và bản ghi gốc.","Luật Dữ liệu số 60/2024/QH15 và quy định về bảo vệ dữ liệu cá nhân (Nghị định 13/2023/NĐ-CP, Luật Bảo vệ dữ liệu cá nhân năm 2025)."],en:["DAMA-DMBOK version 2 with 11 data management knowledge areas and data governance at the center.","The ISO/IEC 25012 data quality model and the ISO 8000 data quality series, including its master data parts.","Common quality dimensions: completeness, validity, uniqueness, accuracy, consistency, timeliness.","Master data management (MDM): record matching, survivorship rules and golden records.","Vietnam's Law on Data No. 60/2024/QH15 and personal data protection rules (Decree 13/2023/ND-CP, the 2025 Personal Data Protection Law)."]},tools:["SQL / Python (pandas)","Công cụ data profiling","Danh mục dữ liệu (data catalog)","Nền tảng quản lý dữ liệu chủ (MDM)","Bảng điều khiển BI chất lượng dữ liệu"],kpis:{vi:["Tỷ lệ phần tử dữ liệu trọng yếu có chủ sở hữu, định nghĩa và quy tắc chất lượng.","Điểm chất lượng tổng hợp của CDE so với ngưỡng đã phê duyệt.","Thời gian trung bình xử lý dứt điểm một sự cố dữ liệu.","Tỷ lệ quy tắc chất lượng được giám sát tự động hằng ngày."],en:["Share of critical data elements with an owner, a definition and quality rules.","Aggregate CDE quality score against the approved threshold.","Average time to fully resolve a data incident.","Share of quality rules monitored automatically every day."]},day:[{time:"08:30",vi:"Xem bảng điều khiển chất lượng dữ liệu, kiểm tra các quy tắc bị đỏ trong đêm.",en:"Review the data quality dashboard and check rules that turned red overnight."},{time:"10:00",vi:"Họp với người quản lý dữ liệu khách hàng để phân tích nguyên nhân gốc của bản ghi trùng.",en:"Meet the customer data steward to analyze the root cause of duplicate records."},{time:"13:30",vi:"Viết quy tắc kiểm tra mới bằng SQL và cập nhật định nghĩa vào danh mục dữ liệu.",en:"Write a new SQL check and update the definition in the data catalog."},{time:"15:30",vi:"Rà soát yêu cầu chia sẻ dữ liệu với đối tác, đối chiếu phân loại và thỏa thuận xử lý.",en:"Review a partner data sharing request against classification and the processing agreement."},{time:"17:00",vi:"Cập nhật nhật ký sự cố dữ liệu và chuẩn bị tài liệu cho hội đồng dữ liệu.",en:"Update the data incident log and prepare material for the data council."}],mistakes:{vi:["Đếm cả bản ghi gốc là bản ghi trùng, làm sai tỷ lệ duy nhất và quy mô xử lý.","Sửa dữ liệu trực tiếp ở kho đích mà không sửa tại nguồn, khiến lỗi quay lại sau mỗi lần nạp.","Chia sẻ dữ liệu cá nhân cho nhà thầu qua kênh cá nhân, không có thỏa thuận và không tối thiểu hóa."],en:["Counting golden records as duplicates, distorting the uniqueness rate and the fix scope.","Patching data in the target store without fixing the source, so errors return with every load.","Sharing personal data with a vendor through personal channels, without an agreement or minimization."]},career:[{vi:"Chuyên viên phân tích chất lượng dữ liệu",en:"Data quality analyst"},{vi:"Người quản lý dữ liệu miền nghiệp vụ (Data Steward)",en:"Domain data steward"},{vi:"Trưởng nhóm quản trị & chất lượng dữ liệu",en:"Data governance & quality lead"},{vi:"Giám đốc dữ liệu (CDO)",en:"Chief Data Officer (CDO)"}],glossary:[{term:"Data Steward",vi:"Người quản lý dữ liệu, chịu trách nhiệm định nghĩa, chất lượng và sử dụng đúng dữ liệu của một miền.",en:"The person accountable for definitions, quality and proper use of a data domain."},{term:"Golden record",vi:"Bản ghi gốc duy nhất, đáng tin cậy nhất của một thực thể sau khi khớp và hợp nhất các bản trùng.",en:"The single most trusted record of an entity after matching and merging duplicates."},{term:"Data lineage",vi:"Dòng dữ liệu: mô tả nguồn gốc, các bước biến đổi và nơi sử dụng của một phần tử dữ liệu.",en:"A description of where a data element comes from, how it is transformed and where it is used."},{term:"CDE",vi:"Phần tử dữ liệu trọng yếu, có tác động lớn tới báo cáo, quyết định hoặc tuân thủ nên được kiểm soát chặt.",en:"Critical data element with high impact on reporting, decisions or compliance, hence tightly controlled."},{term:"Data profiling",vi:"Phân tích thống kê dữ liệu để phát hiện giá trị rỗng, trùng lặp, sai định dạng và bất thường.",en:"Statistical analysis of data to find nulls, duplicates, format errors and anomalies."}],quiz:[{q:{vi:"Bảng có 10.000 bản ghi, phát hiện 200 nhóm trùng gồm tổng cộng 500 bản ghi. Tỷ lệ duy nhất là bao nhiêu?",en:"A table has 10,000 records with 200 duplicate groups totaling 500 records. What is the uniqueness rate?"},options:{vi:["95%","97%","98%","99,5%"],en:["95%","97%","98%","99.5%"]},answer:1,explain:{vi:"Bản ghi thừa = 500 - 200 = 300; tỷ lệ duy nhất = (10.000 - 300) / 10.000 = 97%.",en:"Redundant records = 500 - 200 = 300; uniqueness = (10,000 - 300) / 10,000 = 97%."}},{q:{vi:"Quy tắc kiểm tra mã tỉnh phải thuộc danh mục hành chính đã ban hành đo chiều chất lượng nào?",en:"A rule checking that the province code belongs to the official list measures which dimension?"},options:{vi:["Đầy đủ (Completeness)","Kịp thời (Timeliness)","Duy nhất (Uniqueness)","Hợp lệ (Validity)"],en:["Completeness","Timeliness","Uniqueness","Validity"]},answer:3,explain:{vi:"Giá trị thuộc miền giá trị hoặc định dạng cho phép là chiều hợp lệ.",en:"Values conforming to the allowed domain or format reflect validity."}},{q:{vi:"Nhà thầu đề nghị gửi toàn bộ dữ liệu khách hàng kèm số căn cước qua kênh cá nhân cho kịp tiến độ. Bạn làm gì?",en:"A vendor asks for the full customer data with ID numbers through a personal channel to save time. What do you do?"},options:{vi:["Từ chối, chỉ chia sẻ dữ liệu tối thiểu qua kênh được duyệt và báo chủ sở hữu dữ liệu","Gửi ngay vì nhà thầu đã ký hợp đồng triển khai","Nén file có mật khẩu rồi gửi qua kênh cá nhân","Chờ nhà thầu tự lấy dữ liệu từ hệ thống"],en:["Refuse, share only minimal data through an approved channel and inform the data owner","Send it now because the vendor signed the project contract","Zip the file with a password and send it through the personal channel","Wait for the vendor to pull the data themselves"]},answer:0,explain:{vi:"Chia sẻ dữ liệu cá nhân phải có căn cứ, thỏa thuận xử lý, tối thiểu hóa và qua kênh được kiểm soát.",en:"Sharing personal data requires a legal basis, a processing agreement, minimization and a controlled channel."}},{q:{vi:"Ai phê duyệt định nghĩa và ngưỡng chất lượng của một miền dữ liệu trong mô hình quản trị chuẩn?",en:"In a standard governance model, who approves the definitions and quality thresholds of a data domain?"},options:{vi:["Nhà thầu phần mềm","Quản trị viên cơ sở dữ liệu","Chủ sở hữu dữ liệu (Data Owner)","Bất kỳ người dùng nào"],en:["The software vendor","The database administrator","The data owner","Any user"]},answer:2,explain:{vi:"Chủ sở hữu dữ liệu chịu trách nhiệm giải trình về miền dữ liệu; người quản lý dữ liệu và bộ phận CNTT hỗ trợ thực thi.",en:"The data owner is accountable for the domain; stewards and IT support execution."}}],tools_en:["SQL / Python (pandas)","Data profiling tools","Data catalog","Master data management (MDM) platform","Data quality BI dashboards"]}}})})(window.KKR);
